import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"FewUI Kit","description":"","frontmatter":{},"headers":[],"relativePath":"kit/index.md","filePath":"kit/index.md"}'),s={name:"kit/index.md"};function n(r,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="fewui-kit" tabindex="-1">FewUI Kit <a class="header-anchor" href="#fewui-kit" aria-label="Permalink to &quot;FewUI Kit&quot;">​</a></h1><p>FewUI is not only a Vue component library. It is an <strong>AI-native design system</strong>: components, design tokens, Cursor rules, and agent skills share one contract so humans and AI assistants build UIs with the same vocabulary.</p><h2 id="what-kit-includes" tabindex="-1">What Kit includes <a class="header-anchor" href="#what-kit-includes" aria-label="Permalink to &quot;What Kit includes&quot;">​</a></h2><ul><li><strong><code>ui-*</code> components</strong> — forms, dialogs, tables, navigation, and more.</li><li><strong>Theme packages</strong> — <code>defineTheme</code> + light/dark tokens, generated <code>color.css</code>, <code>ui-theme-provider</code> for scoped preview.</li><li><strong>Themes</strong> — <code>web</code> (admin panel), <code>liquidglass</code> (iOS), <code>android</code> (Material 3), <code>landing</code> (tenant sites), <code>fewui</code>.</li><li><strong>Types and component data</strong> — generated declarations for every <code>ui-*</code> tag and a machine-readable <code>components.json</code>.</li><li><strong>Playground</strong> — live component gallery with a theme sidebar (<a href="https://fewui-docs.pages.dev" target="_blank" rel="noreferrer">fewui-docs.pages.dev</a>).</li><li><strong>Rules &amp; skills</strong> — exportable Cursor rules and <code>SKILL.md</code> for agent workflows.</li></ul><h2 id="ai-first-philosophy" tabindex="-1">AI-first philosophy <a class="header-anchor" href="#ai-first-philosophy" aria-label="Permalink to &quot;AI-first philosophy&quot;">​</a></h2><p>Traditional UI kits document props for humans. FewUI also documents <strong>decisions</strong>:</p><ul><li>Which component to use for a pattern (never raw <code>&lt;button&gt;</code> for primary actions).</li><li>How errors surface (<code>ui-alert</code>, API message helpers).</li><li>How theming flows from a single <code>primaryColor</code> to accents and SSR.</li></ul><p>Restta (restaurant POS, web module, landing) is the reference production app built on Kit.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./getting-started.html">Getting started</a></li><li><a href="./components/">Components</a></li><li><a href="./theming.html">Theming</a></li><li><a href="./localization.html">Localization &amp; RTL</a></li><li><a href="./accessibility.html">Accessibility</a></li><li><a href="./tooling.html">TypeScript &amp; tooling</a></li><li><a href="./skills-and-rules.html">Skills &amp; rules</a></li></ul>',10)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
